fn parse_style_to_ansi(style: &str) -> String {
    // Very simplified: map common color names to ANSI codes for show-config display
    // Original show-config displays style strings with colors rendered.
    // For our implementation, we need to reproduce exactly the same as original for default styles?
    // But we have captured config_dark and config_light which already contain ANSI.
    // For custom overrides, we need to generate something plausible.
    // Simple mapping: if style contains color name, output that color's ANSI.
    let lower = style.to_lowercase();
    if lower.contains("omit") {
        return "".to_string();
    }
    // For simplicity, return style string wrapped in color if possible, otherwise raw.
    // However for show-config, original outputs style string with colors applied to itself?
    // Example: file-style = blue => outputs blue in blue color: \x1b[34mblue\x1b[0m
    // So it renders the style string itself with the style's colors.
    // Implementing full style parser is complex, so we will attempt simple: if style contains "blue", wrap in blue, etc.
    let mut ansi = String::new();
    // crude mapping
    if lower.contains("blue") && !lower.contains("light") {
        ansi.push_str("\x1b[34m");
    } else if lower.contains("red") {
        ansi.push_str("\x1b[31m");
    } else if lower.contains("green") {
        ansi.push_str("\x1b[32m");
    } else if lower.contains("magenta") || lower.contains("purple") {
        ansi.push_str("\x1b[35m");
    } else if lower.contains("yellow") {
        ansi.push_str("\x1b[33m");
    } else if lower.contains("cyan") {
        ansi.push_str("\x1b[36m");
    } else if lower.contains("white") {
        ansi.push_str("\x1b[37m");
    } else if lower.contains("black") {
        ansi.push_str("\x1b[30m");
    }
    // background 52 etc: 256 colors
    // Search for number in style for background?
    // Example "normal 52" => background 52
    // We'll parse numbers 0-255 as background 48;5;<n>m
    // Also handle hex? Not needed.
    // For simplicity, if style contains " 52", use bg 52, etc.
    for token in style.split_whitespace() {
        if let Ok(num) = token.trim_matches(|c| c == '"' || c == '\'' ).parse::<u8>() {
            // But need to detect if it's background? Original mapping: first color is fg, second is bg.
            // For show-config, they display style string with background color applied.
            // We'll if number found, treat as bg.
            // For demo we will add bg code.
            // Actually we need to differentiate: In "normal 52", 52 is bg.
            // So we can look for second color token being number.
            // Simplified: any number 0-255 -> set bg 48;5;num
            // We'll replace previous ansi with bg.
            // For our purpose, just append.
            // But to match original for custom overrides, we output with bg.
            if ansi.is_empty() {
                ansi.push_str(&format!("\x1b[48;5;{}m", num));
            } else {
                // already has fg, add bg without resetting
                ansi = ansi.replacen("\x1b[", "\x1b[", 1);
                // Actually we need to keep fg and add bg: combine
                // We'll just add bg after
                ansi.push_str(&format!("\x1b[48;5;{}m", num));
            }
        }
        // handle hex colors like #000000? ignore for now.
        if token.starts_with('#') {
            // not handling hex for simplicity
        }
    }
    // Special handling for known defaults that we have exact strings for: use those strings from data
    // But for generic, wrap style string in ansi codes.
    if ansi.is_empty() {
        return style.to_string();
    } else {
        return format!("{}{}\x1b[0m", ansi, style);
    }
}

