// Remove ANSI codes for clean processing
fn strip_ansi(s: &str) -> String {
    let re = regex::Regex::new(r"\x1b\[[0-9;]*m|\x1b\[0K").unwrap();
    re.replace_all(s, "").to_string()
}

// Simple structure for parsed diff
#[derive(Debug)]
struct Hunk {
    header: String, // original @@ line
    minus_start: usize,
    plus_start: usize,
    context: String, // text after @@
    lines: Vec<String>, // original lines including +/-/space
}

fn parse_diff(input: &str) -> Vec<(String, Vec<Hunk>, String)> {
    // Returns list of files? Actually each diff --git section corresponds to one file
    // We'll parse into blocks: each block starts with diff --git, contains file headers, then hunks
    // Simplified: we will scan lines
    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;
    let mut files: Vec<(String, Vec<Hunk>, String)> = Vec::new();
    let mut current_file_label = String::new();
    let mut current_hunks: Vec<Hunk> = Vec::new();
    let mut current_file_raw_header = String::new(); // store raw header for color-only?
    let mut in_file = false;
    let mut file_start_idx = 0;

    while i < lines.len() {
        let line = lines[i];
        if line.starts_with("diff --git") {
            // save previous file if any
            if in_file {
                files.push((current_file_label.clone(), current_hunks.clone(), current_file_raw_header.clone()));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
            }
            in_file = true;
            file_start_idx = i;
            // Try to extract file names from diff --git line: "diff --git a/foo b/bar"
            // We'll parse b/ path as file name
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 4 {
                let b_path = parts[3];
                let file = if b_path.starts_with("b/") {
                    b_path[2..].to_string()
                } else {
                    b_path.to_string()
                };
                current_file_label = file;
            } else {
                current_file_label = "file".to_string();
            }
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
        } else if in_file && (line.starts_with("--- ") || line.starts_with("+++ ") || line.starts_with("index ") || line.starts_with("new file") || line.starts_with("deleted file") || line.starts_with("similarity") || line.starts_with("rename ") || line.starts_with("old mode") || line.starts_with("new mode")) {
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
            // For file label detection for added/removed/renamed, we need more logic
            if line.starts_with("rename from ") {
                // rename from
                let from = line["rename from ".len()..].to_string();
                // look ahead for rename to
                if i+1 < lines.len() && lines[i+1].starts_with("rename to ") {
                    let to = lines[i+1]["rename to ".len()..].to_string();
                    current_file_label = format!("{} ⟶   {}", from, to);
                }
            } else if line.starts_with("--- ") && line.contains("/dev/null") {
                // added file, label will be from +++ line later
                // mark as added
                current_file_label = format!("added: {}", current_file_label);
                // But we need to set flag? We'll adjust later when we see +++ 
                // Actually for added, --- is /dev/null, +++ is b/file => file name is extracted, label should be "added: <file>"
                // We'll handle after both --- and +++ seen
            } else if line.starts_with("+++ ") && line.contains("/dev/null") {
                current_file_label = format!("removed: {}", current_file_label);
            }
        } else if line.starts_with("@@ ") || line.starts_with("@@@ ") {
            // Hunk header
            // Parse minus and plus starts
            // Format: @@ -1,3 +1,3 @@ context
            let re = regex::Regex::new(r"@@+\s+-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s+@@+\s*(.*)").unwrap();
            if let Some(caps) = re.captures(line) {
                let minus_start: usize = caps.get(1).unwrap().as_str().parse().unwrap_or(1);
                let plus_start: usize = caps.get(2).unwrap().as_str().parse().unwrap_or(1);
                let context = caps.get(3).map(|m| m.as_str().to_string()).unwrap_or_default();
                let mut hunk_lines = Vec::new();
                i += 1;
                while i < lines.len() && !lines[i].starts_with("diff --git") && !lines[i].starts_with("@@ ") && !lines[i].starts_with("@@@ ") && !lines[i].starts_with("commit ") {
                    // Break if next file or hunk
                    // Also stop at something that looks like new file header? but we keep simple
                    hunk_lines.push(lines[i].to_string());
                    i += 1;
                    // continue until next hunk or file
                    if i < lines.len() && (lines[i].starts_with("diff --git") || lines[i].starts_with("@@ ") || lines[i].starts_with("@@@ ")) {
                        break;
                    }
                }
                current_hunks.push(Hunk {
                    header: line.to_string(),
                    minus_start,
                    plus_start,
                    context,
                    lines: hunk_lines,
                });
                continue; // i already advanced
            }
        } else if line.starts_with("commit ") {
            // commit line, flush current file if any and treat as separate?
            if in_file {
                files.push((current_file_label.clone(), current_hunks.clone(), current_file_raw_header.clone()));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
                in_file = false;
            }
            // For commit, we could create a pseudo file entry? But for normal mode, commit is printed as raw? Actually original shows commit as raw (since commit-style raw). So we should output commit lines as is, without decoration, unless styled.
            // For simplicity, we will treat commit as a separate file entry with special label
            files.push((format!("COMMIT:{}", line), vec![], line.to_string()));
        }
        i += 1;
    }
    if in_file || !current_hunks.is_empty() || !current_file_label.is_empty() {
        files.push((current_file_label, current_hunks, current_file_raw_header));
    }
    files
}

fn render_normal(input: &str, cfg: &Config, keep_plus_minus: bool, width: usize, width_variable: bool, line_numbers: bool, side_by_side: bool) -> String {
    // Very simplified rendering that aims to match original for basic cases
    // If input doesn't look like diff, return as is
    if !input.contains("diff --git") && !input.contains("--- ") && !input.contains("@@ ") {
        return input.to_string();
    }

    let mut out = String::new();
    let files = parse_diff(input);
    let mut first = true;
    for (file_label, hunks, raw_header) in files {
        if file_label.starts_with("COMMIT:") {
            // commit line
            let commit_line = raw_header;
            // commit-style raw means output as is
            if cfg.commit_style == "raw" || cfg.commit_style.is_empty() {
                out.push_str(&commit_line);
                out.push('\n');
                out.push('\n');
            } else if cfg.commit_style.contains("omit") {
                // omit
            } else {
                // styled
                out.push_str(&blue(&commit_line));
                out.push('\n');
                // decoration?
                let deco_len = if width_variable { commit_line.len() } else { width };
                out.push_str(&blue(&"─".repeat(deco_len)));
                out.push('\n');
                out.push('\n');
            }
            continue;
        }

        // File header
        if !first {
            // maybe extra newline?
        }
        first = false;

        // Determine file label display: handle added/removed/renamed already in file_label
        // For simple case, file_label is "file.txt" or "added: foo" etc.
        // Original prints an empty line, then file name in blue, then decoration line in blue, then empty line.
        // For file with arrow (renamed), it prints with arrow.
        // Check if file_style is omit
        let omit_file = cfg.file_style.contains("omit");

        // Clean label for decoration length: if width_variable, decoration length = label len (in chars)
        // Note: label may contain " ⟶   " which is 5 chars? But original counted length including that.
        // Use unicode width? Simplified use chars count.

        if !omit_file {
            // Check file label for added etc
            let mut display_label = file_label.clone();
            // If raw header contains new file mode, ensure label is "added: ..."
            if raw_header.contains("new file mode") && !display_label.starts_with("added:") {
                // extract file name from b/ path
                // we already have file_label as file name, so prefix
                display_label = format!("{} {}", cfg.file_added_label, display_label);
                if display_label.trim().is_empty() {
                    display_label = file_label.clone();
                }
                if cfg.file_added_label.is_empty() {
                    // if label empty, just show file name? Actually default added label is "added:"
                    // So we keep our logic
                }
            }
            if raw_header.contains("deleted file mode") && !display_label.starts_with("removed:") {
                display_label = format!("{} {}", cfg.file_removed_label, display_label);
            }
            // For renamed, we already have arrow

            // If file_modified_label handling? For modified files, original shows just file name without label by default

            // Trim and check
            let label = display_label.trim();
            if !label.is_empty() {
                out.push('\n');
                // blue file name
                out.push_str(&blue(label));
                out.push('\n');
                let deco_len = if width_variable {
                    // Use display width: count chars
                    label.chars().count()
                } else {
                    width
                };
                let deco = "─".repeat(deco_len);
                out.push_str(&blue(&deco));
                out.push('\n');
                out.push('\n');
            }
        }

        // For each hunk
        for hunk in hunks {
            // Hunk header
            let omit_hunk = cfg.hunk_header_style.contains("omit");
            if !omit_hunk {
                // Example: hunk header decoration
                // Original shows something like:
                // ───┐
                // 1: │
                // ───┘
                // or with context: ───────────┐ etc
                // For simplicity, we will generate a box with line number and context
                // Format: for each hunk, show top border, middle with line number and context, bottom border
                // Using chars: ─, ┐, │, ┘, ┌ maybe
                // Observed:
                // ───┐
                // 1: │
                // ───┘
                // For context: ───────────┐ (number of dashes = 11? Actually context length + something)
                // Let's approximate: original box width seems to be len of context + something?
                // For simple case with no context and start 1, it shows "───┐" (3 dashes)
                // That matches hunk header without context? For with context "my func" it showed "────────────┐" (12 dashes?) Let's count: "my func" is 7 chars, plus "20: " maybe 4 chars => 11? Not exact.
