#[derive(Debug, Clone)]
struct Hunk {
    header: String,
    minus_start: usize,
    plus_start: usize,
    context: String,
    lines: Vec<String>,
}

fn parse_diff(input: &str) -> Vec<(String, Vec<Hunk>, String, bool, bool)> {
    // Returns list of files: (label, hunks, raw_header, is_added, is_removed)
    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;
    let mut files: Vec<(String, Vec<Hunk>, String, bool, bool)> = Vec::new();
    let mut current_file_label = String::new();
    let mut current_hunks: Vec<Hunk> = Vec::new();
    let mut current_file_raw_header = String::new();
    let mut in_file = false;
    let mut is_added = false;
    let mut is_removed = false;
    let mut rename_from: Option<String> = None;
    let mut rename_to: Option<String> = None;

    while i < lines.len() {
        let line = lines[i];
        if line.starts_with("diff --git") {
            if in_file {
                // push previous
                // finalize label for added/removed/renamed
                let mut label = current_file_label.clone();
                if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
                    label = format!("{} ⟶   {}", f, t);
                } else if is_added {
                    // file name is current_file_label, but we want added: label
                    // check if already prefixed
                    if !label.starts_with("added:") {
                        label = format!("added: {}", label);
                    }
                } else if is_removed {
                    if !label.starts_with("removed:") {
                        label = format!("removed: {}", label);
                    }
                }
                files.push((label, current_hunks.clone(), current_file_raw_header.clone(), is_added, is_removed));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
                is_added = false;
                is_removed = false;
                rename_from = None;
                rename_to = None;
            }
            in_file = true;
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 4 {
                let b_path = parts[3];
                let file = if b_path.starts_with("b/") { b_path[2..].to_string() } else { b_path.to_string() };
                current_file_label = file;
            } else {
                current_file_label = "file".to_string();
            }
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
        } else if in_file && (line.starts_with("--- ") || line.starts_with("+++ ") || line.starts_with("index ") || line.starts_with("new file") || line.starts_with("deleted file") || line.starts_with("similarity") || line.starts_with("rename ") || line.starts_with("old mode") || line.starts_with("new mode") || line.starts_with("Binary") ) {
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
            if line.starts_with("rename from ") {
                rename_from = Some(line["rename from ".len()..].to_string());
            } else if line.starts_with("rename to ") {
                rename_to = Some(line["rename to ".len()..].to_string());
            } else if line.starts_with("--- ") && line.trim() == "--- /dev/null" {
                is_added = true;
            } else if line.starts_with("+++ ") && line.trim() == "+++ /dev/null" {
                is_removed = true;
            } else if line.starts_with("new file mode") {
                is_added = true;
            } else if line.starts_with("deleted file mode") {
                is_removed = true;
            }
        } else if line.starts_with("@@ ") || line.starts_with("@@@ ") {
            let re = regex::Regex::new(r"@@+\s+-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s+@@+\s*(.*)").unwrap();
            if let Some(caps) = re.captures(line) {
                let minus_start: usize = caps.get(1).unwrap().as_str().parse().unwrap_or(1);
                let plus_start: usize = caps.get(2).unwrap().as_str().parse().unwrap_or(1);
                let context = caps.get(3).map(|m| m.as_str().to_string()).unwrap_or_default();
                let mut hunk_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let l = lines[i];
                    if l.starts_with("diff --git") || l.starts_with("@@ ") || l.starts_with("@@@ ") || l.starts_with("commit ") {
                        break;
                    }
                    hunk_lines.push(l.to_string());
                    i += 1;
                }
                current_hunks.push(Hunk {
                    header: line.to_string(),
                    minus_start,
                    plus_start,
                    context,
                    lines: hunk_lines,
                });
                continue;
            }
        } else if line.starts_with("commit ") {
            if in_file {
                let mut label = current_file_label.clone();
                if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
                    label = format!("{} ⟶   {}", f, t);
                } else if is_added {
                    if !label.starts_with("added:") {
                        label = format!("added: {}", label);
                    }
                } else if is_removed {
                    if !label.starts_with("removed:") {
                        label = format!("removed: {}", label);
                    }
                }
                files.push((label, current_hunks.clone(), current_file_raw_header.clone(), is_added, is_removed));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
                is_added = false;
                is_removed = false;
                rename_from = None;
                rename_to = None;
                in_file = false;
            }
            // commit as separate pseudo entry
            files.push((format!("COMMIT:{}", line), vec![], line.to_string(), false, false));
        }
        i += 1;
    }
    if in_file || !current_hunks.is_empty() || !current_file_label.is_empty() {
        let mut label = current_file_label.clone();
        if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
            label = format!("{} ⟶   {}", f, t);
        } else if is_added {
            if !label.starts_with("added:") {
                label = format!("added: {}", label);
            }
        } else if is_removed {
            if !label.starts_with("removed:") {
                label = format!("removed: {}", label);
            }
        }
        files.push((label, current_hunks, current_file_raw_header, is_added, is_removed));
    }
    files
}

fn render_normal(input: &str, cfg: &Config, keep_plus_minus: bool, width: usize, width_variable: bool, line_numbers: bool, side_by_side: bool) -> String {
    if !input.contains("diff --git") && !input.contains("--- ") && !input.contains("@@ ") && !input.contains("commit ") {
        return input.to_string();
    }
    let mut out = String::new();
    let files = parse_diff(input);
    let is_light = cfg.syntax_theme == "GitHub" || cfg.minus_style.contains("224");
    for (file_label, hunks, raw_header, _is_added, _is_removed) in files {
        if file_label.starts_with("COMMIT:") {
            let commit_line = raw_header;
            if cfg.commit_style.contains("omit") {
                continue;
            }
            if cfg.commit_style == "raw" || cfg.commit_style.is_empty() {
                out.push_str(&commit_line);
                out.push('\n');
                out.push('\n');
            } else {
                out.push_str(&blue(&commit_line));
                out.push('\n');
                let deco_len = if width_variable { commit_line.chars().count() } else { width };
                out.push_str(&blue(&"─".repeat(deco_len)));
                out.push('\n');
                out.push('\n');
            }
            continue;
        }

        let omit_file = cfg.file_style.contains("omit");
        if !omit_file {
            let display_label = if file_label.starts_with("added:") || file_label.starts_with("removed:") || file_label.contains("⟶") {
                file_label.clone()
            } else if raw_header.contains("new file mode") && !file_label.starts_with("added:") {
                format!("added: {}", file_label)
            } else if raw_header.contains("deleted file mode") && !file_label.starts_with("removed:") {
                format!("removed: {}", file_label)
            } else {
                file_label.clone()
            };
            let label = display_label.trim();
            if !label.is_empty() {
                out.push('\n');
                out.push_str(&blue(label));
                out.push('\n');
                let deco_len = if width_variable {
                    label.chars().count()
                } else {
                    width
                };
                let deco = "─".repeat(deco_len);
                out.push_str(&blue(&deco));
                out.push('\n');
                out.push('\n');
            }
        }

        for hunk in hunks {
            let omit_hunk = cfg.hunk_header_style.contains("omit");
            if !omit_hunk {
                let line_num = hunk.plus_start;
                let ctx = &hunk.context;
                let middle_content = if ctx.is_empty() {
                    format!("{}: ", line_num)
                } else {
                    format!("{}: {} ", line_num, ctx)
                };
                let deco_len = middle_content.chars().count();
                let top = format!("{}┐", "─".repeat(deco_len));
                let bottom = format!("{}┘", "─".repeat(deco_len));
                out.push_str(&blue(&top));
                out.push('\n');
                // middle line: line num blue, context with syntax? We will output context as white for simplicity with blue pipe
                out.push_str(&blue(&format!("{}", line_num)));
                out.push_str(": ");
                if !ctx.is_empty() {
                    out.push_str(&format!("\x1b[38;5;231m{}\x1b[0m ", ctx));
                }
                out.push_str(&blue("│"));
                out.push('\n');
                out.push_str(&blue(&bottom));
                out.push('\n');
            }

            let mut line_num_minus = hunk.minus_start;
            let mut line_num_plus = hunk.plus_start;

            if side_by_side {
                // Simplified side-by-side: we output each line with minus/plus bg, but also include line numbers
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let left_num = line_num_minus;
                        line_num_minus += 1;
                        // produce left side with minus
                        out.push_str(&format!("\x1b[34m│\x1b[38;5;88m{:>3} \x1b[34m│\x1b[48;5;52;38;5;231m{}\x1b[0m\x1b[48;5;52m\x1b[0K\x1b[0m\n", left_num, content));
                    } else if l.starts_with('+') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let right_num = line_num_plus;
                        line_num_plus += 1;
                        out.push_str(&format!("\x1b[48;5;22;38;5;231m{}\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m\n", content));
                        let _ = right_num;
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        let ln_m = line_num_minus;
                        let ln_p = line_num_plus;
                        line_num_minus += 1;
                        line_num_plus += 1;
                        out.push_str(&format!("\x1b[38;5;231m{}\x1b[0m\n", content));
                        let _ = (ln_m, ln_p);
                    }
                }
            } else if line_numbers {
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let left_num = line_num_minus;
                        line_num_minus += 1;
                        out.push_str(&format!("{:>3} ⋮    │{}\n", left_num, bg_minus_dark(&content, is_light)));
                    } else if l.starts_with('+') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let right_num = line_num_plus;
                        line_num_plus += 1;
                        out.push_str(&format!("    ⋮ {:>3} │{}\n", right_num, bg_plus_dark(&content, is_light)));
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        let left_num = line_num_minus;
                        let right_num = line_num_plus;
                        line_num_minus += 1;
                        line_num_plus += 1;
                        out.push_str(&format!("{:>3} ⋮ {:>3} │\x1b[38;5;231m{}\x1b[0m\n", left_num, right_num, content));
                    }
                }
            } else {
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        out.push_str(&bg_minus_dark(&content, is_light));
                        out.push('\n');
                    } else if l.starts_with('+') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        out.push_str(&bg_plus_dark(&content, is_light));
                        out.push('\n');
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        out.push_str(&format!("\x1b[38;5;231m{}\x1b[0m\n", content));
                    }
                }
            }
        }
    }
    if out.is_empty() {
        return input.to_string();
    }
    out
}

fn render_color_only(input: &str, _cfg: &Config) -> String {
    let mut out = String::new();
    for line in input.lines() {
        let stripped = strip_ansi(line);
        if stripped.starts_with("--- ") || stripped.starts_with("+++ ") || stripped.starts_with("@@") || stripped.starts_with("diff --git") || stripped.starts_with("index ") || stripped.starts_with("commit ") {
            out.push_str(line);
            out.push('\n');
        } else if stripped.starts_with('-') && !stripped.starts_with("--- ") {
            // minus
            // Use bg 52
            out.push_str(&format!("\x1b[48;5;52m{}\x1b[0m\x1b[48;5;52m\x1b[0K\x1b[0m\n", line));
        } else if stripped.starts_with('+') && !stripped.starts_with("+++ ") {
            // plus with syntax? Use bg 22 and white foreground for content after +
            // We will output plus marker plus content with white and maybe emph? For simplicity, output with bg 22 and white
            let content = if line.starts_with('+') { &line[1..] } else { line };
            // If content already has ANSI? We'll strip and then color?
            // For color-only, original output was: "\x1b[48;5;22m+\x1b[38;5;231mworld\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m"
            // So it keeps '+' with bg 22, then white for non-emph? Let's mimic
            out.push_str(&format!("\x1b[48;5;22m+\x1b[38;5;231m{}\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m\n", strip_ansi(content)));
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    out
}

fn render_raw(input: &str) -> String {
    let mut out = String::new();
    for line in input.lines() {
        let stripped = strip_ansi(line);
        if (stripped.starts_with('-') && !stripped.starts_with("--- ")) || (stripped.starts_with('+') && !stripped.starts_with("+++ ")) {
            if stripped.starts_with('-') {
                if line.contains("\x1b[31m") {
                    out.push_str(line);
                } else {
                    out.push_str(&red_fg(&stripped));
                }
                out.push('\n');
            } else {
                if line.contains("\x1b[32m") {
                    out.push_str(line);
                } else {
                    out.push_str(&green_fg(&stripped));
                }
                out.push('\n');
            }
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    out
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() == 2 && (args[1] == "--version" || args[1] == "-V") {
        println!("delta {}", VERSION);
        return;
    }
    for a in &args {
        if a == "--version" || a == "-V" {
            println!("delta {}", VERSION);
            return;
        }
    }

    let has_short_help = args.iter().any(|a| a == "-h");
    let has_long_help = args.iter().any(|a| a == "--help");
    if has_long_help {
        print!("{}", LONG_HELP);
        return;
    }
    if has_short_help {
        print!("{}", SHORT_HELP);
        return;
    }

    let mut gen_comp_idx = None;
    for (i, a) in args.iter().enumerate() {
        if a == "--generate-completion" {
            gen_comp_idx = Some(i);
            break;
        }
        if a.starts_with("--generate-completion=") {
            let val = a.splitn(2, '=').nth(1).unwrap_or("");
            match val {
                "bash" => { print!("{}", COMP_BASH); return; },
                "zsh" => { print!("{}", COMP_ZSH); return; },
                "fish" => { print!("{}", COMP_FISH); return; },
                "powershell" => { print!("{}", COMP_PS); return; },
                "elvish" => { print!("{}", COMP_ELV); return; },
                _ => {
                    eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--generate-completion <GENERATE_COMPLETION>\x1b[0m'\n  [possible values: \x1b[32mbash\x1b[0m, \x1b[32melvish\x1b[0m, \x1b[32mfish\x1b[0m, \x1b[32mpowershell\x1b[0m, \x1b[32mzsh\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", val);
                    process::exit(2);
                }
            }
        }
    }
    if let Some(idx) = gen_comp_idx {
        if idx + 1 >= args.len() {
            eprintln!("\x1b[1m\x1b[31merror:\x1b[0m a value is required for '\x1b[33m--generate-completion <GENERATE_COMPLETION>\x1b[0m' but none was supplied\n\nFor more information, try '\x1b[1m--help\x1b[0m'.");
            process::exit(2);
        }
        let val = &args[idx+1];
        match val.as_str() {
            "bash" => { print!("{}", COMP_BASH); return; },
            "zsh" => { print!("{}", COMP_ZSH); return; },
            "fish" => { print!("{}", COMP_FISH); return; },
            "powershell" => { print!("{}", COMP_PS); return; },
            "elvish" => { print!("{}", COMP_ELV); return; },
            _ => {
                eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--generate-completion <GENERATE_COMPLETION>\x1b[0m'\n  [possible values: \x1b[32mbash\x1b[0m, \x1b[32melvish\x1b[0m, \x1b[32mfish\x1b[0m, \x1b[32mpowershell\x1b[0m, \x1b[32mzsh\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", val);
                process::exit(2);
            }
        }
    }

    if args.iter().any(|a| a == "--list-languages") {
        print!("{}", LANGS);
        return;
    }
    if args.iter().any(|a| a == "--list-syntax-themes") {
        print!("{}", THEMES_LIST);
        return;
    }
    if args.iter().any(|a| a == "--show-colors") {
        print!("{}", COLORS);
        return;
    }

    let mut cfg = Config::dark();
    let mut is_light_flag = false;
    let mut is_dark_flag = false;
    let mut width_variable = false;
    let mut width_value: usize = 80;
    let mut keep_plus_minus = false;
    let mut line_numbers_flag = false;
    let mut side_by_side_flag = false;
    let mut raw_flag = false;
    let mut color_only_flag = false;
    let mut show_config_flag = false;
    let mut show_syntax_themes_flag = false;
    let mut show_themes_flag = false;
    let mut paging_value = "auto".to_string();

    // To track if any config-override flag present
    let mut has_config_override = false;

    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--dark" => { is_dark_flag = true; cfg = Config::dark(); },
            "--light" => { is_light_flag = true; cfg = Config::light(); },
            "--show-config" => { show_config_flag = true; },
            "--show-syntax-themes" => { show_syntax_themes_flag = true; },
            "--show-themes" => { show_themes_flag = true; },
            "--raw" => { raw_flag = true; },
            "--color-only" => { color_only_flag = true; },
            "--keep-plus-minus-markers" => { keep_plus_minus = true; cfg.keep_plus_minus_markers = true; has_config_override = true; },
            "-n" | "--line-numbers" => { line_numbers_flag = true; cfg.line_numbers = true; has_config_override = true; },
            "-s" | "--side-by-side" => { side_by_side_flag = true; cfg.side_by_side = true; has_config_override = true; },
            "--no-gitconfig" => {},
            "--true-color" => {
                if i+1 < args.len() {
                    let v = &args[i+1];
                    cfg.true_color = if v == "always" { "true".to_string() } else { "false".to_string() };
                    has_config_override = true;
                    i+=1;
                }
            },
            "--width" | "-w" => {
                if i+1 < args.len() {
                    let v = &args[i+1];
                    if v == "variable" {
                        width_variable = true;
                        cfg.width = "variable".to_string();
                    } else if let Ok(num) = v.parse::<usize>() {
                        width_value = num;
                        cfg.width = v.clone();
                    } else {
                        // Check if it's like "80" or expression? For simplicity, if contains '-', try to evaluate? Ignore
                        if v.chars().all(|c| c.is_ascii_digit() || c == '-') {
                            // try to parse as e.g. "74-2" => 72
                            // We'll try simple: split by '-' and subtract? For "74-2" => 72
                            // For our purposes, just extract first number
                            let first = v.split('-').next().unwrap_or("80");
                            if let Ok(num) = first.parse::<usize>() {
                                width_value = num;
                                cfg.width = v.clone();
                            }
                        } else {
                            eprintln!("Invalid value for width: \"{}\" is not an integer", v);
                            process::exit(1);
                        }
                    }
                    has_config_override = true;
                    i+=1;
                }
            },
            "--tabs" => {
                if i+1 < args.len() {
                    cfg.tabs = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            "--syntax-theme" => {
                if i+1 < args.len() {
                    cfg.syntax_theme = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            "--paging" => {
                if i+1 < args.len() {
                    let v = &args[i+1];
                    cfg.paging = v.clone();
                    paging_value = v.clone();
                    if !["auto","always","never"].contains(&v.as_str()) {
                        eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--paging <auto|always|never>\x1b[0m'\n  [possible values: \x1b[32mauto\x1b[0m, \x1b[32malways\x1b[0m, \x1b[32mnever\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", v);
                        process::exit(2);
                    }
                    has_config_override = true;
                    i+=1;
                }
            },
            "--file-style" => {
                if i+1 < args.len() {
                    cfg.file_style = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            "--minus-style" => {
                if i+1 < args.len() {
                    cfg.minus_style = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            "--plus-style" => {
                if i+1 < args.len() {
                    cfg.plus_style = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            "--file-added-label" => {
                if i+1 < args.len() {
                    cfg.file_added_label = args[i+1].clone();
                    has_config_override = true;
                    i+=1;
                }
            },
            _ => {
                if a.starts_with("--true-color=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.true_color = if v == "always" { "true".to_string() } else { "false".to_string() };
                    has_config_override = true;
                } else if a.starts_with("--width=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    if v == "variable" {
                        width_variable = true;
                        cfg.width = "variable".to_string();
                    } else if let Ok(num) = v.parse::<usize>() {
                        width_value = num;
                        cfg.width = v.to_string();
                    } else {
                        eprintln!("Invalid value for width: \"{}\" is not an integer", v);
                        process::exit(1);
                    }
                    has_config_override = true;
                } else if a.starts_with("--tabs=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.tabs = v.to_string();
                    has_config_override = true;
                } else if a.starts_with("--syntax-theme=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.syntax_theme = v.to_string();
                    has_config_override = true;
                } else if a.starts_with("--paging=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.paging = v.to_string();
                    paging_value = v.to_string();
                    if !["auto","always","never"].contains(&cfg.paging.as_str()) {
                        eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--paging <auto|always|never>\x1b[0m'\n  [possible values: \x1b[32mauto\x1b[0m, \x1b[32malways\x1b[0m, \x1b[32mnever\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", v);
                        process::exit(2);
                    }
                    has_config_override = true;
                } else if a.starts_with("--file-style=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.file_style = v.to_string();
                    has_config_override = true;
                } else if a.starts_with("--minus-style=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.minus_style = v.to_string();
                    has_config_override = true;
                } else if a.starts_with("--plus-style=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.plus_style = v.to_string();
                    has_config_override = true;
                } else if a.starts_with("--file-added-label=") {
                    let v = a.splitn(2,'=').nth(1).unwrap_or("");
                    cfg.file_added_label = v.to_string();
                    has_config_override = true;
