        c.minus_style = "normal 224".to_string();
        c.minus_non_emph_style = "normal 224".to_string();
        c.minus_emph_style = "normal 217".to_string();
        c.minus_empty_line_marker_style = "normal 224".to_string();
        c.plus_style = "syntax 194".to_string();
        c.plus_non_emph_style = "syntax 194".to_string();
        c.plus_emph_style = "syntax 157".to_string();
        c.plus_empty_line_marker_style = "normal 194".to_string();
        c.blame_palette = "#FFFFFF #DDDDDD #BBBBBB".to_string();
        c.syntax_theme = "GitHub".to_string();
        c
    }
}

fn parse_style_to_ansi(style: &str) -> String {
    if style == "raw" || style == "syntax" || style == "normal" || style.is_empty() {
        return style.to_string();
    }
    if style.contains('#') {
        let tokens: Vec<&str> = style.split_whitespace().collect();
        let mut parts = Vec::new();
        for token in tokens {
            let bg_code = match token {
                "#000000" => 16,
                "#222222" => 235,
                "#444444" => 238,
                "#FFFFFF" => 231,
                "#DDDDDD" => 253,
                "#BBBBBB" => 250,
                _ => 0,
            };
            if bg_code != 0 {
                parts.push(format!("\x1b[48;5;{}m{}\x1b[0m", bg_code, token));
            } else {
                parts.push(token.to_string());
            }
        }
        return parts.join(" ");
    }
    let mut fg: Option<String> = None;
    let mut bg: Option<String> = None;
    let mut attrs: Vec<u8> = Vec::new();
    let mut color_position = 0;
    for token in style.split_whitespace() {
        let t = token.trim_matches(|c| c == '"' || c == '\'').to_lowercase();
        if t.is_empty() { continue; }
        match t.as_str() {
            "bold" => { if !attrs.contains(&1) { attrs.push(1); } },
            "dim" => { if !attrs.contains(&2) { attrs.push(2); } },
            "italic" => { if !attrs.contains(&3) { attrs.push(3); } },
            "ul" | "underline" => { if !attrs.contains(&4) { attrs.push(4); } },
            "blink" => { if !attrs.contains(&5) { attrs.push(5); } },
            "reverse" => { if !attrs.contains(&7) { attrs.push(7); } },
            "hidden" => { if !attrs.contains(&8) { attrs.push(8); } },
            "strike" => { if !attrs.contains(&9) { attrs.push(9); } },
            "box" | "ol" => {},
            "normal" | "auto" | "raw" | "syntax" => { color_position += 1; },
            _ => {
                let ansi_fg = match t.as_str() {
                    "black" => Some(30),
                    "red" => Some(31),
                    "green" => Some(32),
                    "yellow" => Some(33),
                    "blue" => Some(34),
                    "magenta" | "purple" => Some(35),
                    "cyan" => Some(36),
                    "white" => Some(37),
                    _ => None,
                };
                if let Some(code) = ansi_fg {
                    if color_position == 0 {
                        fg = Some(code.to_string());
                    } else if color_position == 1 {
                        bg = Some((code + 10).to_string());
                    }
                    color_position += 1;
                    continue;
                }
                if let Ok(num) = t.parse::<u8>() {
                    if color_position == 0 {
                        fg = Some(format!("38;5;{}", num));
                    } else if color_position == 1 {
                        bg = Some(format!("48;5;{}", num));
                    }
                    color_position += 1;
                    continue;
                }
            }
        }
    }
    let mut codes: Vec<String> = Vec::new();
    for a in attrs { codes.push(a.to_string()); }
    if let Some(f) = fg { codes.push(f); }
    if let Some(b) = bg { codes.push(b); }
    if codes.is_empty() {
        style.to_string()
    } else {
        format!("\x1b[{}m{}\x1b[0m", codes.join(";"), style)
    }
}

fn blue(s: &str) -> String { format!("\x1b[34m{}\x1b[0m", s) }
fn bg_minus_simple(s: &str) -> String { format!("\x1b[48;5;52m{}\x1b[0m\x1b[48;5;52m\x1b[0K\x1b[0m", s) }
fn bg_minus_simple_variable(s: &str) -> String { format!("\x1b[48;5;52m{}\x1b[0m", s) }
fn bg_plus(s: &str) -> String { format!("\x1b[48;5;22;38;5;231m{}\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m", s) }
fn bg_plus_variable(s: &str) -> String { format!("\x1b[48;5;22;38;5;231m{}\x1b[0m", s) }
fn bg_minus_dark(s: &str, light: bool) -> String {
    if light { format!("\x1b[48;5;224m{}\x1b[0m\x1b[48;5;224m\x1b[0K\x1b[0m", s) } else { bg_minus_simple(s) }
}
fn bg_minus_dark_variable(s: &str, light: bool) -> String {
    if light { format!("\x1b[48;5;224m{}\x1b[0m", s) } else { bg_minus_simple_variable(s) }
}
fn bg_plus_dark(s: &str, light: bool) -> String {
    if light { format!("\x1b[48;5;194m{}\x1b[0m\x1b[48;5;194m\x1b[0K\x1b[0m", s) } else { bg_plus(s) }
}
fn bg_plus_dark_variable(s: &str, light: bool) -> String {
    if light { format!("\x1b[48;5;194m{}\x1b[0m", s) } else { bg_plus_variable(s) }
}
fn red_fg(s: &str) -> String { format!("\x1b[31m{}\x1b[0m", s) }
fn green_fg(s: &str) -> String { format!("\x1b[32m{}\x1b[0m", s) }
fn strip_ansi(s: &str) -> String {
    let re = regex::Regex::new(r"\x1b\[[0-9;]*m|\x1b\[0K").unwrap();
    re.replace_all(s, "").to_string()
}

#[derive(Debug, Clone)]
struct Hunk {
    header: String,
    minus_start: usize,
    plus_start: usize,
    context: String,
    lines: Vec<String>,
}

fn parse_diff(input: &str) -> Vec<(String, Vec<Hunk>, String, bool, bool)> {
    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;
    let mut files: Vec<(String, Vec<Hunk>, String, bool, bool)> = Vec::new();
    let mut current_file_label = String::new();
    let mut current_hunks: Vec<Hunk> = Vec::new();
    let mut current_file_raw_header = String::new();
    let mut in_file = false;
    let mut is_added = false;
    let mut is_removed = false;
    let mut rename_from: Option<String> = None;
    let mut rename_to: Option<String> = None;
    let mut minus_file: Option<String> = None;
    let mut plus_file: Option<String> = None;

    while i < lines.len() {
        let line = lines[i];
        if line.starts_with("diff --git") {
            if in_file {
                let mut label = current_file_label.clone();
                if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
                    label = format!("{} ⟶   {}", f, t);
                } else if is_added {
                    if !label.starts_with("added:") { label = format!("added: {}", label); }
                } else if is_removed {
                    if !label.starts_with("removed:") { label = format!("removed: {}", label); }
                } else if let (Some(mf), Some(pf)) = (&minus_file, &plus_file) {
                    if mf != pf { label = format!("{} ⟶   {}", mf, pf); } else { label = pf.clone(); }
                }
                files.push((label, current_hunks.clone(), current_file_raw_header.clone(), is_added, is_removed));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
                is_added = false;
                is_removed = false;
                rename_from = None;
                rename_to = None;
                minus_file = None;
                plus_file = None;
            }
            in_file = true;
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 4 {
                let b_path = parts[3];
                let file = if b_path.starts_with("b/") { b_path[2..].to_string() } else { b_path.to_string() };
                current_file_label = file;
            } else {
                current_file_label = "file".to_string();
            }
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
        } else if line.starts_with("--- ") {
            if !in_file {
                in_file = true;
                current_file_label = "file".to_string();
                current_file_raw_header.clear();
                current_hunks.clear();
                is_added = false;
                is_removed = false;
                rename_from = None;
                rename_to = None;
                minus_file = None;
                plus_file = None;
            }
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
            let path = line["--- ".len()..].split('\t').next().unwrap_or("").trim();
            let clean_path_raw = if path.starts_with("a/") { &path[2..] } else { path };
            let clean_path = clean_path_raw.trim_start_matches('/').to_string();
            if clean_path_raw == "/dev/null" || clean_path == "dev/null" {
                is_added = true;
            } else {
                minus_file = Some(clean_path.clone());
                if current_file_label == "file" || current_file_label.is_empty() {
                    current_file_label = clean_path.clone();
                }
            }
        } else if line.starts_with("+++ ") {
            if !in_file {
                in_file = true;
                current_file_label = "file".to_string();
                current_file_raw_header.clear();
                current_hunks.clear();
            }
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
            let path = line["+++ ".len()..].split('\t').next().unwrap_or("").trim();
            let clean_path_raw = if path.starts_with("b/") { &path[2..] } else { path };
            let clean_path = clean_path_raw.trim_start_matches('/').to_string();
            if clean_path_raw == "/dev/null" || clean_path == "dev/null" {
                is_removed = true;
            } else {
                plus_file = Some(clean_path.clone());
                if minus_file.is_none() {
                    current_file_label = clean_path.clone();
                } else if let Some(mf) = &minus_file {
                    if mf == &clean_path {
                        current_file_label = clean_path.clone();
                    }
                }
            }
        } else if in_file && (line.starts_with("index ") || line.starts_with("new file") || line.starts_with("deleted file") || line.starts_with("similarity") || line.starts_with("rename ") || line.starts_with("old mode") || line.starts_with("new mode") || line.starts_with("Binary")) {
            current_file_raw_header.push_str(line);
            current_file_raw_header.push('\n');
            if line.starts_with("rename from ") {
                rename_from = Some(line["rename from ".len()..].to_string());
            } else if line.starts_with("rename to ") {
                rename_to = Some(line["rename to ".len()..].to_string());
            } else if line.contains("new file mode") {
                is_added = true;
            } else if line.contains("deleted file mode") {
                is_removed = true;
            }
        } else if line.starts_with("@@ ") || line.starts_with("@@@ ") {
            let re = regex::Regex::new(r"@@+\s+-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s+@@+\s*(.*)").unwrap();
            if let Some(caps) = re.captures(line) {
                let minus_start: usize = caps.get(1).unwrap().as_str().parse().unwrap_or(1);
                let plus_start: usize = caps.get(2).unwrap().as_str().parse().unwrap_or(1);
                let context = caps.get(3).map(|m| m.as_str().to_string()).unwrap_or_default();
                let mut hunk_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let l = lines[i];
                    if l.starts_with("diff --git") || l.starts_with("@@ ") || l.starts_with("@@@ ") || l.starts_with("commit ") || l.starts_with("--- ") {
                        break;
                    }
                    hunk_lines.push(l.to_string());
                    i += 1;
                }
                current_hunks.push(Hunk { header: line.to_string(), minus_start, plus_start, context, lines: hunk_lines, });
                continue;
            }
        } else if line.starts_with("commit ") {
            if in_file {
                let mut label = current_file_label.clone();
                if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
                    label = format!("{} ⟶   {}", f, t);
                } else if is_added {
                    if !label.starts_with("added:") { label = format!("added: {}", label); }
                } else if is_removed {
                    if !label.starts_with("removed:") { label = format!("removed: {}", label); }
                } else if let (Some(mf), Some(pf)) = (&minus_file, &plus_file) {
                    if mf != pf { label = format!("{} ⟶   {}", mf, pf); } else { label = pf.clone(); }
                }
                files.push((label, current_hunks.clone(), current_file_raw_header.clone(), is_added, is_removed));
                current_hunks.clear();
                current_file_label.clear();
                current_file_raw_header.clear();
                is_added = false;
                is_removed = false;
                rename_from = None;
                rename_to = None;
                minus_file = None;
                plus_file = None;
                in_file = false;
            }
            let mut commit_block = String::new();
            commit_block.push_str(line);
            commit_block.push('\n');
            i += 1;
            while i < lines.len() {
                let l = lines[i];
                if l.starts_with("diff --git") || l.starts_with("commit ") || l.starts_with("--- ") {
                    break;
                }
                commit_block.push_str(l);
                commit_block.push('\n');
                i += 1;
            }
            files.push((format!("COMMIT:{}", line), vec![], commit_block, false, false));
            continue;
        }
        i += 1;
    }
    if in_file || !current_hunks.is_empty() || !current_file_label.is_empty() {
        let mut label = current_file_label.clone();
        if let (Some(f), Some(t)) = (&rename_from, &rename_to) {
            label = format!("{} ⟶   {}", f, t);
        } else if is_added {
            if !label.starts_with("added:") { label = format!("added: {}", label); }
        } else if is_removed {
            if !label.starts_with("removed:") { label = format!("removed: {}", label); }
        } else if let (Some(mf), Some(pf)) = (&minus_file, &plus_file) {
            if mf != pf { label = format!("{} ⟶   {}", mf, pf); } else { label = pf.clone(); }
        }
        files.push((label, current_hunks, current_file_raw_header, is_added, is_removed));
    }
    files
}

fn render_normal(input: &str, cfg: &Config, keep_plus_minus: bool, width: usize, width_variable: bool, line_numbers: bool, side_by_side: bool) -> String {
    if !input.contains("diff --git") && !input.contains("--- ") && !input.contains("@@ ") && !input.contains("commit ") {
        return input.to_string();
    }
    let mut out = String::new();
    let files = parse_diff(input);
    let is_light = cfg.syntax_theme == "GitHub" || cfg.minus_style.contains("224");
    for (file_label, hunks, raw_header, _is_added, _is_removed) in files {
        if file_label.starts_with("COMMIT:") {
            let commit_block = raw_header;
            if cfg.commit_style.contains("omit") { continue; }
            if cfg.commit_style == "raw" || cfg.commit_style.is_empty() {
                out.push_str(&commit_block);
            } else {
                out.push_str(&blue(&commit_block));
                let deco_len = if width_variable { commit_block.lines().next().map(|l| l.chars().count()).unwrap_or(0) } else { width };
                out.push_str(&blue(&"─".repeat(deco_len)));
                out.push('\n');
                out.push('\n');
            }
            continue;
        }
        let omit_file = cfg.file_style.contains("omit");
        if !omit_file {
            let display_label = if file_label.starts_with("added:") || file_label.starts_with("removed:") || file_label.contains("⟶") {
                file_label.clone()
            } else if raw_header.contains("new file mode") && !file_label.starts_with("added:") {
                format!("added: {}", file_label)
            } else if raw_header.contains("deleted file mode") && !file_label.starts_with("removed:") {
                format!("removed: {}", file_label)
            } else {
                file_label.clone()
            };
            let label = display_label.trim();
            if !label.is_empty() {
                out.push('\n');
                out.push_str(&blue(label));
                out.push('\n');
                let deco_len = if width_variable { label.chars().count() } else { width };
                let deco = "─".repeat(deco_len);
                out.push_str(&blue(&deco));
                out.push('\n');
                out.push('\n');
            }
        }
        for hunk in hunks {
            let omit_hunk = cfg.hunk_header_style.contains("omit");
            if !omit_hunk {
                let line_num = hunk.plus_start;
                let ctx = &hunk.context;
                let middle_content = if ctx.is_empty() { format!("{}: ", line_num) } else { format!("{}: {} ", line_num, ctx) };
                let deco_len = middle_content.chars().count();
                let dashes = "─".repeat(deco_len);
                out.push_str(&blue(&dashes));
                out.push_str(&blue("┐"));
                out.push('\n');
                out.push_str(&blue(&format!("{}", line_num)));
                out.push_str(": ");
                if !ctx.is_empty() {
                    out.push_str(&format!("\x1b[38;5;231m {} \x1b[0m", ctx));
                }
                out.push_str(&blue("│"));
                out.push('\n');
                out.push_str(&blue(&dashes));
                out.push_str(&blue("┘"));
                out.push('\n');
            }
            let mut line_num_minus = hunk.minus_start;
            let mut line_num_plus = hunk.plus_start;
            if side_by_side {
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let left_num = line_num_minus;
                        line_num_minus += 1;
                        if width_variable {
                            out.push_str(&format!("\x1b[34m│\x1b[38;5;88m{:>3} \x1b[34m│\x1b[48;5;52;38;5;231m{}\x1b[0m\n", left_num, content));
                        } else {
                            out.push_str(&format!("\x1b[34m│\x1b[38;5;88m{:>3} \x1b[34m│\x1b[48;5;52;38;5;231m{}\x1b[0m\x1b[48;5;52m\x1b[0K\x1b[0m\n", left_num, content));
                        }
                    } else if l.starts_with('+') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        line_num_plus += 1;
                        if width_variable {
                            out.push_str(&format!("\x1b[48;5;22;38;5;231m{}\x1b[0m\n", content));
                        } else {
                            out.push_str(&format!("\x1b[48;5;22;38;5;231m{}\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m\n", content));
                        }
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        line_num_minus += 1;
                        line_num_plus += 1;
                        out.push_str(&format!("\x1b[38;5;231m{}\x1b[0m\n", content));
                    }
                }
            } else if line_numbers {
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let left_num = line_num_minus;
                        line_num_minus += 1;
                        if width_variable {
                            out.push_str(&format!("{:>3} ⋮    │{}\n", left_num, bg_minus_dark_variable(&content, is_light)));
                        } else {
                            out.push_str(&format!("{:>3} ⋮    │{}\n", left_num, bg_minus_dark(&content, is_light)));
                        }
                    } else if l.starts_with('+') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        let right_num = line_num_plus;
                        line_num_plus += 1;
                        if width_variable {
                            out.push_str(&format!("    ⋮ {:>3} │{}\n", right_num, bg_plus_dark_variable(&content, is_light)));
                        } else {
                            out.push_str(&format!("    ⋮ {:>3} │{}\n", right_num, bg_plus_dark(&content, is_light)));
                        }
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        let left_num = line_num_minus;
                        let right_num = line_num_plus;
                        line_num_minus += 1;
                        line_num_plus += 1;
                        out.push_str(&format!("{:>3} ⋮ {:>3} │\x1b[38;5;231m{}\x1b[0m\n", left_num, right_num, content));
                    }
                }
            } else {
                for l in &hunk.lines {
                    if l.starts_with('-') {
                        let content = if keep_plus_minus { l.clone() } else { l[1..].to_string() };
                        if width_variable {
                            out.push_str(&bg_minus_dark_variable(&content, is_light));
                        } else {
                            out.push_str(&bg_minus_dark(&content, is_light));
                        }
                        out.push('\n');
                    } else if l.starts_with('+') {
                        if keep_plus_minus {
                            let full = l;
                            let rest = if full.len() > 1 { &full[1..] } else { "" };
                            if width_variable {
                                out.push_str(&format!("\x1b[48;5;{}m+\x1b[38;5;231m{}\x1b[0m\n", if is_light { 194 } else { 22 }, rest));
                            } else {
                                out.push_str(&format!("\x1b[48;5;{}m+\x1b[38;5;231m{}\x1b[0m\x1b[48;5;{}m\x1b[0K\x1b[0m\n", if is_light { 194 } else { 22 }, rest, if is_light { 194 } else { 22 }));
                            }
                        } else {
                            let content = l[1..].to_string();
                            if width_variable {
                                out.push_str(&bg_plus_dark_variable(&content, is_light));
                            } else {
                                out.push_str(&bg_plus_dark(&content, is_light));
                            }
                            out.push('\n');
                        }
                    } else {
                        let content = if l.starts_with(' ') { l[1..].to_string() } else { l.clone() };
                        out.push_str(&format!("\x1b[38;5;231m{}\x1b[0m\n", content));
                    }
                }
            }
        }
    }
    if out.is_empty() { return input.to_string(); }
    out
}

fn render_color_only(input: &str, _cfg: &Config) -> String {
    let mut out = String::new();
    for line in input.lines() {
        let stripped = strip_ansi(line);
        if stripped.starts_with("--- ") || stripped.starts_with("+++ ") || stripped.starts_with("@@") || stripped.starts_with("diff --git") || stripped.starts_with("index ") || stripped.starts_with("commit ") {
            out.push_str(line);
            out.push('\n');
        } else if stripped.starts_with('-') && !stripped.starts_with("--- ") {
            out.push_str(&format!("\x1b[48;5;52m{}\x1b[0m\x1b[48;5;52m\x1b[0K\x1b[0m\n", line));
        } else if stripped.starts_with('+') && !stripped.starts_with("+++ ") {
            let content = if line.starts_with('+') { &line[1..] } else { line };
            out.push_str(&format!("\x1b[48;5;22m+\x1b[38;5;231m{}\x1b[0m\x1b[48;5;22m\x1b[0K\x1b[0m\n", strip_ansi(content)));
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    out
}

fn render_raw(input: &str) -> String {
    let mut out = String::new();
    for line in input.lines() {
        let stripped = strip_ansi(line);
        if (stripped.starts_with('-') && !stripped.starts_with("--- ")) || (stripped.starts_with('+') && !stripped.starts_with("+++ ")) {
            if stripped.starts_with('-') {
                if line.contains("\x1b[31m") {
                    out.push_str(line);
                } else {
                    out.push_str(&red_fg(&stripped));
                }
                out.push('\n');
            } else {
                if line.contains("\x1b[32m") {
                    out.push_str(line);
                } else {
                    out.push_str(&green_fg(&stripped));
                }
                out.push('\n');
            }
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    out
}

