        if buf.is_empty() { String::new() } else { buf }
    };
    let output = if raw_flag {
        render_raw(&stdin_data)
    } else if color_only_flag {
        render_color_only(&stdin_data, &cfg)
    } else {
        render_normal(&stdin_data, &cfg, keep_plus_minus, width_value, width_variable, line_numbers_flag, side_by_side_flag)
    };
    let mut stdout = io::stdout();
    let _ = stdout.write_all(output.as_bytes());
}
