                "elvish" => { print!("{}", COMP_ELV); return; },
                _ => {
                    eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--generate-completion <GENERATE_COMPLETION>\x1b[0m'\n  [possible values: \x1b[32mbash\x1b[0m, \x1b[32melvish\x1b[0m, \x1b[32mfish\x1b[0m, \x1b[32mpowershell\x1b[0m, \x1b[32mzsh\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", val);
                    process::exit(2);
                }
            }
        }
    }
    if let Some(idx) = gen_comp_idx {
        if idx + 1 >= args.len() {
            eprintln!("\x1b[1m\x1b[31merror:\x1b[0m a value is required for '\x1b[33m--generate-completion <GENERATE_COMPLETION>\x1b[0m' but none was supplied\n\nFor more information, try '\x1b[1m--help\x1b[0m'.");
            process::exit(2);
        }
        let val = &args[idx+1];
        match val.as_str() {
            "bash" => { print!("{}", COMP_BASH); return; },
            "zsh" => { print!("{}", COMP_ZSH); return; },
            "fish" => { print!("{}", COMP_FISH); return; },
            "powershell" => { print!("{}", COMP_PS); return; },
            "elvish" => { print!("{}", COMP_ELV); return; },
            _ => {
                eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m--generate-completion <GENERATE_COMPLETION>\x1b[0m'\n  [possible values: \x1b[32mbash\x1b[0m, \x1b[32melvish\x1b[0m, \x1b[32mfish\x1b[0m, \x1b[32mpowershell\x1b[0m, \x1b[32mzsh\x1b[0m]\n\nFor more information, try '\x1b[1m--help\x1b[0m'.", val);
                process::exit(2);
            }
        }
    }
    if args.iter().any(|a| a == "--list-languages") {
        print!("{}", LANGS);
        return;
    }
    if args.iter().any(|a| a == "--list-syntax-themes") {
        print!("{}", THEMES_LIST);
        return;
    }
    if args.iter().any(|a| a == "--show-colors") {
        print!("{}", COLORS);
        return;
    }
    let mut cfg = Config::dark();
    let mut is_light_flag = false;
    let mut is_dark_flag = false;
    let mut width_variable = false;
    let mut width_value: usize = 80;
    let mut keep_plus_minus = false;
