    let mut color_only_flag = false;
    let mut show_config_flag = false;
    let mut show_syntax_themes_flag = false;
    let mut show_themes_flag = false;
    let mut has_style_override = false;

    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--dark" => { is_dark_flag = true; cfg = Config::dark(); },
            "--light" => { is_light_flag = true; cfg = Config::light(); },
            "--show-config" => { show_config_flag = true; },
            "--show-syntax-themes" => { show_syntax_themes_flag = true; },
