            "-n" | "--line-numbers" => { line_numbers_flag = true; cfg.line_numbers = true; has_style_override = true; },
            "-s" | "--side-by-side" => { side_by_side_flag = true; cfg.side_by_side = true; has_style_override = true; },
            "--no-gitconfig" => {},
            "--true-color" => {
