            "--minus-style" => { if i+1 < args.len() { cfg.minus_style = args[i+1].clone(); has_style_override = true; i+=1; } },
            "--plus-style" => { if i+1 < args.len() { cfg.plus_style = args[i+1].clone(); has_style_override = true; i+=1; } },
            "--file-added-label" => { if i+1 < args.len() { cfg.file_added_label = args[i+1].clone(); has_style_override = true; i+=1; } },
            _ => {
