                println!("\nSyntax theme: \x1b[1m{}\x1b[0m\n", theme_name);
                println!("\x1b[34mexample.rs\x1b[0m");
                println!("\x1b[34m──────────\x1b[0m\n");
                println!("\x1b[34m───\x1b[0m\x1b[34m┐\x1b[0m");
                println!("\x1b[34m1\x1b[0m: \x1b[34m│\x1b[0m");
                println!("\x1b[34m───\x1b[0m\x1b[34m┘\x1b[0m");
                println!("\x1b[48;5;52m// Output the square of a number.\x1b[0m");
                println!("\x1b[48;5;22m// Output the cube of a number.\x1b[0m");
                println!();
            }
        }
        return;
    }
