    while i < args.len() {
        let a = &args[i];
        if a.starts_with('-') {
            let flags_with_value = [
                "--blame-code-style","--blame-format","--blame-palette","--blame-separator-format","--blame-separator-style","--blame-timestamp-format","--blame-timestamp-output-format",
                "--config","--commit-decoration-style","--commit-regex","--commit-style","--default-language","--detect-dark-light","--diff-args","--diff-stat-align-width","--features",
                "--file-added-label","--file-copied-label","--file-decoration-style","--file-modified-label","--file-removed-label","--file-renamed-label","--file-style","--file-transformation",
                "--generate-completion","--grep-context-line-style","--grep-file-style","--grep-header-decoration-style","--grep-header-file-style","--grep-line-number-style","--grep-output-type","--grep-match-line-style","--grep-match-word-style","--grep-separator-symbol",
                "--hunk-header-decoration-style","--hunk-header-file-style","--hunk-header-line-number-style","--hunk-header-style","--hunk-label","--hyperlinks-commit-link-format","--hyperlinks-file-link-format","--inline-hint-style","--inspect-raw-lines",
                "--line-buffer-size","--line-fill-method","--line-numbers-left-format","--line-numbers-left-style","--line-numbers-minus-style","--line-numbers-plus-style","--line-numbers-right-format","--line-numbers-right-style","--line-numbers-zero-style",
                "--map-styles","--max-line-distance","--max-syntax-highlighting-length","--max-line-length","--merge-conflict-begin-symbol","--merge-conflict-end-symbol","--merge-conflict-ours-diff-header-decoration-style","--merge-conflict-ours-diff-header-style","--merge-conflict-theirs-diff-header-decoration-style","--merge-conflict-theirs-diff-header-style",
                "--minus-empty-line-marker-style","--minus-emph-style","--minus-non-emph-style","--minus-style","--navigate-regex","--pager","--paging","--plus-emph-style","--plus-empty-line-marker-style","--plus-non-emph-style","--plus-style","--right-arrow","--syntax-theme","--tabs","--true-color","--whitespace-error-style","--width","--word-diff-regex","--wrap-left-symbol","--wrap-max-lines","--wrap-right-percent","--wrap-right-prefix-symbol","--wrap-right-symbol","--zero-style","--24-bit-color",
                "-@"
            ];
            let is_with_value = flags_with_value.iter().any(|k| a == *k || a.starts_with(&format!("{}=", k)));
            if is_with_value && !a.contains('=') { i+=1; }
        } else {
            positional.push(a.clone());
        }
        i+=1;
    }
    let stdin_data = if positional.len() == 2 {
        let minus = &positional[0];
        let plus = &positional[1];
        let output = process::Command::new("diff").arg("-u").arg(minus).arg(plus).output();
        match output {
            Ok(o) => {
                let mut s = String::new();
                s.push_str(&String::from_utf8_lossy(&o.stdout));
                s.push_str(&String::from_utf8_lossy(&o.stderr));
                s
            },
            Err(_) => String::new()
        }
    } else if positional.len() == 0 {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).unwrap_or(0);
        buf
    } else {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).unwrap_or(0);
        if buf.is_empty() { String::new() } else { buf }
    };
    let output = if raw_flag {
        render_raw(&stdin_data)
    } else if color_only_flag {
        render_color_only(&stdin_data, &cfg)
    } else {
        render_normal(&stdin_data, &cfg, keep_plus_minus, width_value, width_variable, line_numbers_flag, side_by_side_flag)
    };
    let mut stdout = io::stdout();
    let _ = stdout.write_all(output.as_bytes());
}
